using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
public static class PropsLoad103Review {
 static readonly string[] Ids={"shells","gravestone","crossgrave","smallbarrel","storagepot","brokenpot","lantern","miningtools","coiledrope"};
 [Serializable]public class Row{public string stage;public int instances,each,samples,visibleRenderers,colliders,lights,meshTriangles;public int uniqueMeshes,uniqueMaterials,uniqueTextures;public long sharedMeshBytes,sharedTextureBytes;public float cpuSubmitMedianMs,cpuSubmitP95Ms,synchronizedMedianMs,synchronizedP95Ms;}
 [Serializable]public class Report{public bool pass,editorOnly=true,gpuTimingMeasured=false;public string device,pipeline;public string[] limitations;public Row[] rows;}
 static float P(List<float> a,float t){a.Sort();return a[Mathf.Min(a.Count-1,(int)(a.Count*t))];}
 public static void Compare(Camera camera,GameObject old,string output,Action draw){old.SetActive(false);var rows=new List<Row>();var originalPosition=camera.transform.position;var originalRotation=camera.transform.rotation;var rt=new RenderTexture(1280,900,24,RenderTextureFormat.ARGB32,RenderTextureReadWrite.sRGB);var pixel=new Texture2D(1,1,TextureFormat.RGB24,false);camera.targetTexture=rt;ShaderUtil.allowAsyncCompilation=false;draw(); // Submit grass once: executeMethod does not advance frames between Camera.Render calls.
 foreach(var stage in new[]{"before","current","candidate"})foreach(int n in new[]{1,25}){
  var group=new GameObject("Density comparison "+stage);group.transform.position=old.transform.position;int side=n==1?3:15;
  for(int k=0;k<n*Ids.Length;k++){string id=Ids[k%Ids.Length];string file=id=="shells"?"Assets/shore96-"+(stage=="before"?"before":"after")+".prefab":"Assets/"+(stage=="before"?"Imported95":stage=="candidate"&&id=="coiledrope"?"Imported104-after":"Imported102-after")+"/small-"+id+".prefab";var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(file);if(!prefab)throw new Exception("Missing existing fixture "+file);var o=(GameObject)PrefabUtility.InstantiatePrefab(prefab);o.transform.SetParent(group.transform,false);o.transform.localPosition=new Vector3((k%side-(side-1)*.5f)*2.2f,0,(k/side-(side-1)*.5f)*2.2f);o.transform.localRotation=Quaternion.Euler(0,(k%4)*.2f*Mathf.Rad2Deg,0);}
  var target=old.transform.position+Vector3.up*.4f;camera.transform.position=target+new Vector3(0,9,-6.3f)*(n==1?1:3.6f);camera.transform.LookAt(target);var renderers=group.GetComponentsInChildren<Renderer>();var mesh=group.GetComponentsInChildren<MeshFilter>().Select(x=>x.sharedMesh).Distinct().ToArray();var mats=renderers.SelectMany(x=>x.sharedMaterials).Distinct().ToArray();var textures=mats.SelectMany(m=>m.GetTexturePropertyNames().Select(p=>m.GetTexture(p))).Where(t=>t).Distinct().ToArray();foreach(var mat in mats)if(ShaderUtil.ShaderHasError(mat.shader))throw new Exception(mat.shader.name);
  for(int k=0;k<4;k++){camera.Render();}var cpu=new List<float>();var sync=new List<float>();for(int k=0;k<12;k++){var watch=System.Diagnostics.Stopwatch.StartNew();camera.Render();cpu.Add((float)watch.Elapsed.TotalMilliseconds);var previous=RenderTexture.active;RenderTexture.active=rt;pixel.ReadPixels(new Rect(0,0,1,1),0,0);pixel.Apply();RenderTexture.active=previous;sync.Add((float)watch.Elapsed.TotalMilliseconds);}
  var planes=GeometryUtility.CalculateFrustumPlanes(camera);rows.Add(new Row{stage=stage,instances=n*Ids.Length,each=n,samples=12,visibleRenderers=renderers.Count(r=>GeometryUtility.TestPlanesAABB(planes,r.bounds)),colliders=group.GetComponentsInChildren<Collider>().Length,lights=group.GetComponentsInChildren<Light>().Length,meshTriangles=mesh.Sum(m=>m.triangles.Length/3),uniqueMeshes=mesh.Length,uniqueMaterials=mats.Length,uniqueTextures=textures.Length,sharedMeshBytes=mesh.Sum(m=>UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(m)),sharedTextureBytes=textures.Sum(t=>UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(t)),cpuSubmitMedianMs=P(cpu,.5f),cpuSubmitP95Ms=P(cpu,.95f),synchronizedMedianMs=P(sync,.5f),synchronizedP95Ms=P(sync,.95f)});
  var prev=RenderTexture.active;RenderTexture.active=rt;var image=new Texture2D(1280,900,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1280,900),0,0);image.Apply();File.WriteAllBytes(Path.Combine(output,stage+"-"+(n*Ids.Length)+".png"),image.EncodeToPNG());RenderTexture.active=prev;UnityEngine.Object.DestroyImmediate(image);group.SetActive(false); // Keep buffers alive until Editor teardown; avoid mid-loop lifetime changes.
  File.WriteAllText(Path.Combine(output,"partial.json"),JsonUtility.ToJson(new Report{pass=false,rows=rows.ToArray()},true));
 }
 foreach(var stage in new[]{"before","current","candidate"}){var a=rows.Single(x=>x.stage==stage&&x.each==1);var b=rows.Single(x=>x.stage==stage&&x.each==25);if(a.uniqueMeshes!=b.uniqueMeshes||a.uniqueMaterials!=b.uniqueMaterials||a.uniqueTextures!=b.uniqueTextures||b.sharedTextureBytes>a.sharedTextureBytes||a.sharedMeshBytes!=b.sharedMeshBytes)throw new Exception("Per-instance asset duplication "+stage);}
 var report=new Report{pass=true,device=SystemInfo.graphicsDeviceName,pipeline="Unity 6000.5.9f1 / URP 17.5, isolated existing generated grassland 71421",rows=rows.ToArray(),limitations=new[]{"Editor CPU camera submission and synchronous 1px readback, not native GPU time or Player frame rate","Existing historical imported geometry/material assets; current compiled shader code; grass submitted once for the synchronous Editor frame","Dense grid is a throughput scenario, not a representative gameplay encounter; mobile untested","No source scene saved, no GUI/input, no Player"}};File.WriteAllText(Path.Combine(output,"load.json"),JsonUtility.ToJson(report,true));camera.targetTexture=null;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(pixel);camera.transform.SetPositionAndRotation(originalPosition,originalRotation);old.SetActive(true);
 }
}
